<?php
require_once __DIR__.'/../config.php';require_once __DIR__.'/lib/Portal.php';require_once __DIR__.'/lib/Layout.php';$ctx=rxp_context($pdo);rxp_require_perm($ctx,'reports');[$scope,$params]=rxp_invoice_scope($ctx,'i');$done="'active','end_of_time','end_of_volume','sendedwarn','send_on_hold'";
function rxpr_rows(PDO $p,string $s,array $x){$q=$p->prepare($s);$q->execute($x);return $q->fetchAll(PDO::FETCH_ASSOC);}function rxpr_one(PDO $p,string $s,array $x){$q=$p->prepare($s);$q->execute($x);return $q->fetchColumn()?:0;}
$revenue=(int)rxpr_one($pdo,"SELECT COALESCE(SUM(CAST(i.price_product AS UNSIGNED)),0) FROM invoice i WHERE $scope AND i.Status IN ($done)",$params);$sales=(int)rxpr_one($pdo,"SELECT COUNT(*) FROM invoice i WHERE $scope",$params);$avg=$sales?intdiv($revenue,$sales):0;$byProduct=rxpr_rows($pdo,"SELECT i.name_product,COUNT(*) c,COALESCE(SUM(CAST(i.price_product AS UNSIGNED)),0) r FROM invoice i WHERE $scope GROUP BY i.name_product ORDER BY r DESC LIMIT 30",$params);$byStatus=rxpr_rows($pdo,"SELECT i.Status,COUNT(*) c FROM invoice i WHERE $scope GROUP BY i.Status ORDER BY c DESC",$params);$byOwner=[];foreach($ctx['scope_ids'] as $oid){$q=$pdo->prepare("SELECT COUNT(*) c,COALESCE(SUM(CAST(price_product AS UNSIGNED)),0) r FROM invoice WHERE refral=? AND Status IN ($done)");$q->execute([$oid]);$v=$q->fetch(PDO::FETCH_ASSOC);$byOwner[]=['id'=>$oid,'c'=>$v['c']??0,'r'=>$v['r']??0];}
rxp_layout_start($ctx,'گزارش فروش','reports.php');?>
<h1 class="rxp-title">گزارش فروش</h1><div class="rxp-grid"><div class="rxp-stat"><b><?=rxp_money($revenue)?></b><span>درآمد موفق</span></div><div class="rxp-stat"><b><?=$sales?></b><span>تعداد سفارش</span></div><div class="rxp-stat"><b><?=rxp_money($avg)?></b><span>میانگین سفارش</span></div></div>
<div class="rxp-card"><h2>فروش بر اساس محصول</h2><div class="rxp-table-wrap"><table class="rxp-table"><tr><th>محصول</th><th>تعداد</th><th>درآمد</th></tr><?php foreach($byProduct as $r):?><tr><td><?=rxp_h($r['name_product']?:'نامشخص')?></td><td><?=$r['c']?></td><td><?=rxp_money($r['r'])?></td></tr><?php endforeach;?></table></div></div><div class="rxp-card"><h2>وضعیت سفارش‌ها</h2><div class="rxp-table-wrap"><table class="rxp-table"><tr><th>وضعیت</th><th>تعداد</th></tr><?php foreach($byStatus as $r):?><tr><td><?=rxp_h($r['Status'])?></td><td><?=$r['c']?></td></tr><?php endforeach;?></table></div></div>
<?php if($ctx['role']==='super'):?><div class="rxp-card"><h2>سهم مستقیم زیرنمایندگان بر اساس refral</h2><table class="rxp-table"><tr><th>شناسه نماینده</th><th>فروش</th><th>درآمد</th></tr><?php foreach($byOwner as $r):?><tr><td><?=rxp_h($r['id'])?></td><td><?=$r['c']?></td><td><?=rxp_money($r['r'])?></td></tr><?php endforeach;?></table></div><?php endif;?><?php rxp_layout_end();
